package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonAutoDetect.Visibility;
import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.cfg.*;
import com.fasterxml.jackson.databind.cfg.MapperFeature;
import com.fasterxml.jackson.databind.cfg.VisibilityChecker;
import com.fasterxml.jackson.databind.deser.DeserializationProblemHandler;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.jsontype.*;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.LinkedNode;
import com.fasterxml.jackson.databind.util.RootNameLookup;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

/**
 * Unit tests for DeserializationConfig#getDefaultVisibilityChecker
 */
public class DeserializationConfig_getDefaultVisibilityChecker_TriageGen0Test {

    private BaseSettings baseSettings;
    private SubtypeResolver subtypeResolver;
    private SimpleMixInResolver mixins;
    private RootNameLookup rootNames;

    @Before
    public void setUp() {
        baseSettings = Mockito.mock(BaseSettings.class);
        subtypeResolver = Mockito.mock(SubtypeResolver.class);
        mixins = Mockito.mock(SimpleMixInResolver.class);
        rootNames = Mockito.mock(RootNameLookup.class);
    }

    /**
     * Test case where all AUTO_DETECT features are ENABLED.
     * The visibility checker should remain as returned by super.getDefaultVisibilityChecker().
     */
    @Test
    public void testGetDefaultVisibilityChecker_AllFeaturesEnabled() {
        DeserializationConfig config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames);

        // Mock baseSettings to return true for all relevant MapperFeatures
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_SETTERS)).thenReturn(true);
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_CREATORS)).thenReturn(true);
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_FIELDS)).thenReturn(true);

        VisibilityChecker<?> checker = config.getDefaultVisibilityChecker();

        // Since we can't easily check the "original" state without knowing super's implementation,
        // we verify that the features being disabled didn't trigger a change to NONE.
        // In a standard Jackson setup, default visibility is usually ALL.
        assertEquals(Visibility.ANY, checker.getGetterVisibility());
        assertEquals(Visibility.ANY, checker.getSetterVisibility());
        assertEquals(Visibility.ANY, checker.getFieldVisibility());
    }

    /**
     * Test case where AUTO_DETECT_SETTERS is DISABLED.
     */
    @Test
    public void testGetDefaultVisibilityChecker_SettersDisabled() {
        DeserializationConfig config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames);

        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_SETTERS)).thenReturn(false);
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_CREATORS)).thenReturn(true);
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_FIELDS)).thenReturn(true);

        VisibilityChecker<?> checker = config.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getSetterVisibility());
        assertEquals(Visibility.ANY, checker.getGetterVisibility());
        assertEquals(Visibility.ANY, checker.getFieldVisibility());
    }

    /**
     * Test case where AUTO_DETECT_CREATORS is DISABLED.
     */
    @Test
    public void testGetDefaultVisibilityChecker_CreatorsDisabled() {
        DeserializationConfig config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames);

        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_SETTERS)).thenReturn(true);
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_CREATORS)).thenReturn(false);
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_FIELDS)).thenReturn(true);

        VisibilityChecker<?> checker = config.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getCreatorVisibility());
        assertEquals(Visibility.ANY, checker.getSetterVisibility());
        assertEquals(Visibility.ANY, checker.getFieldVisibility());
    }

    /**
     * Test case where AUTO_DETECT_FIELDS is DISABLED.
     */
    @Test
    public void testGetDefaultVisibilityChecker_FieldsDisabled() {
        DeserializationConfig config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames);

        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_SETTERS)).thenReturn(true);
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_CREATORS)).thenReturn(true);
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_FIELDS)).thenReturn(false);

        VisibilityChecker<?> checker = config.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getFieldVisibility());
        assertEquals(Visibility.ANY, checker.getSetterVisibility());
        assertEquals(Visibility.ANY, checker.getCreatorVisibility());
    }

    /**
     * Test case where ALL AUTO_DETECT features are DISABLED.
     */
    @Test
    public void testGetDefaultVisibilityChecker_AllFeaturesDisabled() {
        DeserializationConfig config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames);

        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_SETTERS)).thenReturn(false);
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_CREATORS)).thenReturn(false);
        when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_FIELDS)).thenReturn(false);

        VisibilityChecker<?> checker = config.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getSetterVisibility());
        assertEquals(Visibility.NONE, checker.getCreatorVisibility());
        assertEquals(Visibility.NONE, checker.getFieldVisibility());
    }
}
